function mapSeats(slots, limit, mapper, signal) {
  if (!Number.isInteger(limit) || limit < 1 || limit > 3) {
    return Promise.reject(new RangeError("limit must be an integer from 1 to 3"));
  }

  return new Promise((resolve, reject) => {
    const length = slots.length;
    const indices = [];

    for (let i = 0; i < length; i++) {
      if (Object.prototype.hasOwnProperty.call(slots, i)) {
        indices.push(i);
      }
    }

    const result = new Array(length);

    if (signal.aborted) {
      reject(signal.reason);
      return;
    }

    let next = 0;
    let active = 0;
    let completed = 0;
    let settled = false;

    const finish = (reason, failed) => {
      if (settled) return;
      settled = true;
      signal.removeEventListener("abort", onAbort);

      if (failed) {
        reject(reason);
      } else {
        resolve(result);
      }
    };

    function onAbort() {
      finish(signal.reason, true);
    }

    signal.addEventListener("abort", onAbort);

    const launch = () => {
      while (!settled && active < limit && next < indices.length) {
        const index = indices[next++];
        let value;

        try {
          value = mapper(slots[index], index);
        } catch (error) {
          finish(error, true);
          return;
        }

        active++;

        Promise.resolve(value).then(
          mapped => {
            active--;

            if (settled) return;

            result[index] = mapped;
            completed++;

            if (completed === indices.length) {
              finish(undefined, false);
            } else {
              launch();
            }
          },
          reason => {
            active--;
            finish(reason, true);
          }
        );

        if (settled) return;
      }

      if (!settled && indices.length === 0) {
        finish(undefined, false);
      }
    };

    launch();
  });
}
